16	package io.helidon.tracing.opentelemetry;
17	
18	import java.util.Map;
19	import java.util.Objects;
20	import java.util.Optional;
21	
22	import io.helidon.common.context.Contexts;
23	import io.helidon.tracing.Scope;
24	import io.helidon.tracing.Span;
25	import io.helidon.tracing.SpanContext;
26	
27	import io.opentelemetry.api.baggage.Baggage;
28	import io.opentelemetry.api.baggage.BaggageBuilder;
29	import io.opentelemetry.api.baggage.BaggageEntry;
30	import io.opentelemetry.api.common.Attributes;
31	import io.opentelemetry.api.common.AttributesBuilder;
32	import io.opentelemetry.api.trace.StatusCode;
33	import io.opentelemetry.context.Context;
34	
35	class OpenTelemetrySpan implements Span {
36	    private final io.opentelemetry.api.trace.Span delegate;
37	
38	    OpenTelemetrySpan(io.opentelemetry.api.trace.Span span) {
39	        this.delegate = span;
40	    }
41	
42	    @Override
43	    public Span tag(String key, String value) {
44	        delegate.setAttribute(key, value);
45	        return this;
46	    }
47	
48	    @Override
49	    public Span tag(String key, Boolean value) {
50	        delegate.setAttribute(key, value);
51	        return this;
52	    }
53	
54	    @Override
55	    public Span tag(String key, Number value) {
56	        if (value instanceof Double || value instanceof Float) {
57	            delegate.setAttribute(key, value.doubleValue());
58	        } else {
59	            delegate.setAttribute(key, value.longValue());
60	        }
61	        return this;
62	    }
63	
64	    @Override
65	    public void status(Status status) {
66	        switch (status) {
67	        case OK -> delegate.setStatus(StatusCode.OK);
68	        case ERROR -> delegate.setStatus(StatusCode.ERROR);
69	        default -> {
70	        }
71	        }
72	    }
73	
74	    @Override
75	    public SpanContext context() {
76	        return new OpenTelemetrySpanContext(Context.current().with(delegate));
77	    }
78	
79	    @Override
80	    public void addEvent(String name, Map<String, ?> attributes) {
81	        delegate.addEvent(name, toAttributes(attributes));
82	    }
83	
84	    @Override
85	    public void end() {
86	        delegate.end();
87	    }
88	
89	    @Override
90	    public void end(Throwable t) {
91	        delegate.recordException(t);
92	        delegate.setStatus(StatusCode.ERROR);
93	        delegate.end();
94	    }
95	
96	    @Override
97	    public Scope activate() {
98	        return new OpenTelemetryScope(delegate.makeCurrent());
99	    }
100	
101	    @Override
102	    public Span baggage(String key, String value) {
103	        Objects.requireNonNull(key, "Baggage Key cannot be null");
104	        Objects.requireNonNull(value, "Baggage Value cannot be null");
105	
106	        BaggageBuilder baggageBuilder = Baggage.builder();
107	
108	        //Check for previously added baggage items
109	        Map<String, BaggageEntry> baggageEntryMap = Baggage.fromContext(getContext()).asMap();
110	        baggageEntryMap.forEach((k, v) -> baggageBuilder.put(k, v.getValue()));
111	
112	        baggageBuilder
113	                .put(key, value)
114	                .build()
115	                .storeInContext(getContext()
116	                        .with(delegate))
117	                .makeCurrent();
118	        return this;
119	    }
120	
121	    @Override
122	    public Optional<String> baggage(String key) {
123	        Objects.requireNonNull(key, "Baggage Key cannot be null");
124	        return Optional.ofNullable(Baggage.fromContext(getContext()).getEntryValue(key));
125	    }
126	
127	    // Check if OTEL Context is already available in Global Helidon Context.
128	    // If not – use Current context.
129	    private static Context getContext() {
130	        return Contexts.context()
131	                .flatMap(ctx -> ctx.get(Context.class))
132	                .orElseGet(Context::current);
133	    }
134	
135	    private Attributes toAttributes(Map<String, ?> attributes) {
136	        AttributesBuilder builder = Attributes.builder();
137	        attributes.forEach((key, value) -> {
138	            if (value instanceof Long l) {
139	                builder.put(key, l);
140	            } else if (value instanceof Boolean b) {
141	                builder.put(key, b);
142	            } else if (value instanceof Double d) {
143	                builder.put(key, d);
144	            } else {
145	                builder.put(key, String.valueOf(value));
146	            }
147	        });
148	        return builder.build();
149	    }
150	}
