16	package io.helidon.tracing.opentelemetry;
17	
18	import java.util.Map;
19	import java.util.Optional;
20	
21	import io.helidon.config.Config;
22	import io.helidon.tracing.HeaderConsumer;
23	import io.helidon.tracing.HeaderProvider;
24	import io.helidon.tracing.Span;
