package io.helidon.tracing.opentelemetry;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.BiConsumer;

import io.opentelemetry.api.baggage.Baggage;
import io.opentelemetry.api.baggage.BaggageBuilder;
import io.opentelemetry.api.baggage.BaggageEntry;
import io.opentelemetry.api.baggage.BaggageEntryMetadata;

/**
 * A mutable implementation of OpenTelemetry {@link io.opentelemetry.api.baggage.Baggage}.
 * <p>
 * The stock OpenTelemetry {@code Baggage} is immutable which forces a new OTel context scope to be created (via
 * {@code makeCurrent()}) each time baggage is added. Helidon allows baggage to be added to an already-activated span, so this
 * class stores baggage entries in a mutable map without disturbing the current OTel context. The baggage is made current only as
 * part of activating the span.
 */
class MutableOpenTelemetryBaggage implements Baggage {

    private final Map<String, BaggageEntry> values;
    private final Map<String, BaggageEntry> valuesView;

    MutableOpenTelemetryBaggage() {
        this.values = new LinkedHashMap<>();
        this.valuesView = Collections.unmodifiableMap(values);
    }

    private MutableOpenTelemetryBaggage(Builder builder) {
        this.values = new LinkedHashMap<>();
        this.valuesView = Collections.unmodifiableMap(values);
        this.values.putAll(builder.values);
    }

    @Override
    public int size() {
        return values.size();
    }

    @Override
    public void forEach(BiConsumer<? super String, ? super BaggageEntry> consumer) {
        values.forEach(consumer);
    }

    @Override
    public Map<String, BaggageEntry> asMap() {
        return valuesView;
    }

    @Override
    public String getEntryValue(String entryKey) {
        BaggageEntry entry = values.get(entryKey);
        return entry != null ? entry.getValue() : null;
    }

    @Override
    public BaggageBuilder toBuilder() {
        return new Builder(values);
    }

    void baggage(String key, String value) {
        values.put(key, new HBaggageEntry(value, new HBaggageEntryMetadata("")));
    }

    static class Builder implements BaggageBuilder {

        private final Map<String, BaggageEntry> values = new java.util.HashMap<>();

        private Builder(Map<String, BaggageEntry> values) {
            this.values.putAll(values);
        }

        @Override
        public BaggageBuilder put(String key, String value, BaggageEntryMetadata entryMetadata) {
            values.put(key, new HBaggageEntry(value, entryMetadata));
            return this;
        }

        @Override
        public BaggageBuilder remove(String key) {
            values.remove(key);
            return this;
        }

        @Override
        public Baggage build() {
            return new MutableOpenTelemetryBaggage(this);
        }
    }

    record HBaggageEntry(String value, BaggageEntryMetadata metadata) implements BaggageEntry {

        @Override
        public String getValue() {
            return value;
        }

        @Override
        public BaggageEntryMetadata getMetadata() {
            return metadata;
        }
    }

    record HBaggageEntryMetadata(String metadata) implements BaggageEntryMetadata {

        @Override
        public String getValue() {
            return metadata;
        }
    }
}
