import io.opentelemetry.api.OpenTelemetry;
import io.opentelemetry.context.Context;
import io.opentelemetry.sdk.OpenTelemetrySdk;
import io.opentelemetry.sdk.trace.SdkTracerProvider;

import org.junit.jupiter.api.Test;

import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.containsString;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.is;
import static org.hamcrest.Matchers.not;

class TmpVerifyTest {

    @Test
    void verify() {
        OpenTelemetry otel = OpenTelemetrySdk.builder()
                .setTracerProvider(SdkTracerProvider.builder().build())
                .build();
        Tracer tracer = new OpenTelemetryTracer.Builder().openTelemetry(otel).build();

        Span span = tracer.spanBuilder("s").start();

        // non-no-op span id
        String spanId = span.context().spanId();
        assertThat(spanId, not(containsString("00000000")));

        Context before = Context.current();
        try (Scope scope = span.activate()) {
            // current span id matches
            Optional<Span> cur = Span.current();
            assertThat(cur.isPresent(), is(true));
            assertThat(cur.get().context().spanId(), equalTo(spanId));

            span.baggage("k", "v");
            assertThat(span.baggage("k").get(), equalTo("v"));
        }
        // context fully restored
        assertThat(Context.current(), is(before));
        span.end();
    }
}
